<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
require_login();
require_once __DIR__.'/includes/music-file-repair.php';
$user=current_user();$pdo=db();if(!$pdo){http_response_code(503);exit('Database unavailable.');}
$workspace=music_workspace_resources_v330_resolve_active($pdo,$user,max(0,(int)($_GET['workspace']??0)));
if(!$workspace){http_response_code(403);exit('No accessible Music Workspace was found.');}
$workspaceId=(int)$workspace['id'];
try{$inventory=music_file_repair_inventory($pdo,$workspaceId,$user);}catch(DomainException $e){http_response_code(403);exit('Track management access is required.');}
