$selected=null;$kind=(string)($_GET['kind']??'');$id=max(0,(int)($_GET['id']??0));foreach($inventory as $row)if($row['kind']===$kind&&$row['id']===$id)$selected=$row;
if(!$selected&&$id>0){try{$target=music_file_repair_target($pdo,$workspaceId,$user,$kind,$id);$selected=$target+['master'=>music_file_repair_status((string)(($target['source']??$target['catalog'])['audio_path']??'')),'revision'=>music_file_repair_revision($target)];}catch(Throwable $e){}}
$notice=flash('notice');$error=flash('error');
$rows=$all?$inventory:array_values(array_filter($inventory,static fn(array $row):bool=>$row['missing']));
$memberHeaderUser=$user;$memberHeaderTitle='Music files';$memberHeaderSubtitle=(string)$workspace['workspace_name'];$memberHeaderActions='';
$self=url('/music-file-repair.php?workspace='.$workspaceId);
