.repair-main{display:flex;flex-direction:column;min-height:0;overflow:hidden;min-width:0;background:#f7f7f8}.repair-wrap{flex:1;min-height:0;overflow-y:auto;width:100%;max-width:1080px;margin:0 auto;padding:24px 20px 70px}.repair-card{border:1px solid #dfe1e4;border-radius:15px;background:white;padding:20px;margin:14px 0;min-width:0}.repair-card h2,.repair-card h3{margin-top:0}.repair-card p,.repair-card li{line-height:1.55;overflow-wrap:anywhere}.repair-actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:12px 0}.repair-btn{display:inline-flex;justify-content:center;align-items:center;border:1px solid #d2d5d9;background:white;color:#202226;border-radius:9px;padding:10px 13px;text-decoration:none;font:inherit;cursor:pointer}.repair-btn.primary{background:#202226;color:white;border-color:#202226}.repair-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:16px}.repair-note{color:#60646a;font-size:13px}.repair-alert{color:#963424}.repair-form{display:grid;gap:14px}.repair-form input[type=file]{width:100%;max-width:100%;min-width:0}.repair-form label{display:grid;gap:8px;font-weight:700}.repair-form button{justify-self:start}@media(max-width:650px){.repair-wrap{padding:12px 12px 65px}.repair-card{padding:16px}.repair-row{grid-template-columns:1fr}.repair-actions>*{flex:1 1 140px}}
